"""GSExplorer+ Player tests with real media generated by ffmpeg (headless).

Run: QT_QPA_PLATFORM=offscreen python tests/test_player.py
"""
import os
import shutil
import subprocess
import sys
import tempfile
import time

H = tempfile.mkdtemp(prefix="gx-player-")
os.environ.update(HOME=H, XDG_CONFIG_HOME=f"{H}/.config", XDG_DATA_HOME=f"{H}/.local/share",
                  XDG_CACHE_HOME=f"{H}/.cache")
os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

if not shutil.which("ffmpeg"):
    print("SKIP: ffmpeg not installed (needed to generate test media)")
    sys.exit(0)

from PySide6.QtWidgets import QApplication  # noqa: E402

app = QApplication([])
from gsexplorer import mediaplayer as mp  # noqa: E402
from gsexplorer import themes  # noqa: E402
from gsexplorer.config import Config  # noqa: E402
from gsexplorer.mainwindow import MainWindow  # noqa: E402

results = []


def check(name, cond):
    results.append(bool(cond))
    print(("PASS " if cond else "FAIL ") + name, flush=True)


def pump(sec=0.2):
    t = time.time()
    while time.time() - t < sec:
        app.processEvents()
        time.sleep(0.01)


def wait(cond, timeout=15):
    t = time.time()
    while not cond():
        pump(0.05)
        if time.time() - t > timeout:
            return False
    return True


def ff(*args):
    subprocess.run(["ffmpeg", "-nostdin", "-loglevel", "error", "-y", *args], check=True)


D = os.path.join(H, "Media")
os.makedirs(D)
ff("-f", "lavfi", "-i", "testsrc=duration=4:size=320x240:rate=25", "-f", "lavfi", "-i", "sine=duration=4",
   "-c:v", "mpeg4", "-c:a", "aac", "-shortest", f"{D}/Clip 2.mp4")
ff("-f", "lavfi", "-i", "sine=frequency=330:duration=3", f"{D}/Clip 10.wav")
ff("-f", "lavfi", "-i", "testsrc2=size=200x200", "-frames:v", "1", f"{D}/cover.jpg")
ff("-f", "lavfi", "-i", "sine=frequency=440:duration=3", "-i", f"{D}/cover.jpg", "-map", "0", "-map", "1",
   "-c:a", "libmp3lame", "-c:v", "mjpeg", "-disposition:v", "attached_pic",
   "-metadata", "title=Test Song", "-metadata", "artist=GX Band", f"{D}/Clip 1.mp3")
ff("-f", "lavfi", "-i", "testsrc=duration=3:size=160x120:rate=25", "-f", "lavfi", "-i", "sine=f=300:d=3",
   "-f", "lavfi", "-i", "sine=f=600:d=3", "-map", "0", "-map", "1", "-map", "2",
   "-c:v", "mpeg4", "-c:a", "aac", "-metadata:s:a:0", "language=eng", "-metadata:s:a:1", "language=spa",
   "-shortest", f"{D}/tracks.mkv")
ff("-f", "lavfi", "-i", "anullsrc=r=8000:cl=mono", "-t", "240", "-c:a", "libmp3lame", "-b:a", "8k",
   f"{os.path.join(H, 'long')}.mp3")
with open(f"{D}/notes.txt", "w") as f:
    f.write("not media")

# ---------------------------------------------------------------- helpers
check("media_kind by extension", mp.media_kind("a.MKV") == "video" and mp.media_kind("b.flac") == "audio"
      and mp.media_kind("c.txt") == "")
pl = [os.path.basename(p) for p in mp.folder_playlist(f"{D}/Clip 2.mp4")]
check("folder playlist: media only, natural order", pl == ["Clip 1.mp3", "Clip 2.mp4", "Clip 10.wav", "tracks.mkv"])
check("time format", mp.fmt_ms(65000) == "1:05" and mp.fmt_ms(3725000) == "1:02:05")

# ---------------------------------------------------------------- window
cfg = Config()
themes.apply(app, cfg["theme"], themes.load_themes())
win = MainWindow(cfg, None)
win.show()
win.left.current().navigate(D)
pump(0.5)
e = next(x for x in win.left.current().model.rows if x.name == "Clip 2.mp4")
win.open_entry(win.left.current(), e)            # double-click / Enter on a video
p = getattr(win, "_player", None)
check("double-click on video opens GSExplorer+ Player", p is not None and p.isVisible())
check("plays the clicked file with the folder as playlist",
      p.current_path().endswith("Clip 2.mp4") and len(p.playlist) == 4 and p.index == 1)
check("video decodes (duration ~4 s)", wait(lambda: abs(p.player.duration() - 4000) < 400))
check("video surface shown", wait(lambda: p.area.currentWidget() is p.video))
check("playing", wait(lambda: p.player.playbackState() == p.QMediaPlayer.PlayingState))
p.toggle()
check("pause", wait(lambda: p.player.playbackState() == p.QMediaPlayer.PausedState))
p.seek_to(2000)
check("seek", wait(lambda: p.player.position() >= 1900))
p.step_speed(1)
p.step_speed(1)
check("speed up to 1.5x", abs(p.player.playbackRate() - 1.5) < 0.01 and p.speed.currentText() == "1.5×")
p.speed.setCurrentIndex(mp.SPEEDS.index(1.0))
p.change_volume(-30)
check("volume change applied", abs(p.audio.volume() - 0.5) < 0.02 and cfg["player_volume"] == 50)
p.toggle_mute()
check("mute", p.audio.isMuted())
p.toggle_mute()

# auto-advance at the end
p.seek_to(3600)
p.player.play()
check("end of file advances to next", wait(lambda: p.current_path().endswith("Clip 10.wav"), 10))
check("audio shows artwork page", wait(lambda: p.area.currentWidget() is p.art))

# previous goes back (position < 3 s)
p.play_index(0, autoplay=False)
check("music tags shown", wait(lambda: "Test Song" in p.now.text() and "GX Band" in p.now.text()))
check("cover art loaded", wait(lambda: p.art._pm is not None))
p.prev()
check("previous from first wraps to last", p.current_path().endswith("tracks.mkv"))
p.play_index(1)
wait(lambda: p.player.position() > 3200, 10)
p.prev()
p.prev()                                          # double-tap quickly, before the seek lands
check("double-tap Previous goes to the previous file", p.current_path().endswith("Clip 1.mp3"))

# tracks
check("audio tracks listed", wait(lambda: len(p.player.audioTracks()) == 2) and p.b_tracks.isEnabled())
p.player.setActiveAudioTrack(1)
check("switch audio track", wait(lambda: p.player.activeAudioTrack() == 1))

# repeat one
p.repeat = "one"
p.play_index(2)                                   # Clip 10.wav (3 s)
wait(lambda: p.player.duration() > 0)
p.seek_to(2700)
p.player.play()
t0 = time.time()
check("repeat-one replays the same file", wait(lambda: p.player.position() < 1000 and time.time() - t0 > 0.5, 10)
      and p.current_path().endswith("Clip 10.wav"))
p.repeat = "off"

# fullscreen
p.toggle_fullscreen()
pump(0.3)
check("fullscreen hides playlist", p.isFullScreen() and not p.side.isVisible())
p.leave_fullscreen()
pump(0.3)
check("leave fullscreen restores playlist", not p.isFullScreen() and p.side.isVisible())

# resume position (files > 3 min)
LONG = os.path.join(H, "long.mp3")
p.open_media(LONG)
check("long file loads", wait(lambda: p.player.duration() > 200000, 15))
p.seek_to(100000)
wait(lambda: p.player.position() >= 99000)
p.play_index(0) if len(p.playlist) > 1 else p.stop()
p.stop()
check("position saved locally", any(v.get("pos", 0) >= 99000 for v in mp.load_positions().values()))
p.open_media(LONG)
check("resumes where you left off", wait(lambda: p.player.position() >= 99000, 15))

# start-at hand-off (preview panel → player)
p.open_media(f"{D}/Clip 2.mp4", start_at=2500)
check("start-at position honoured", wait(lambda: p.player.position() >= 2400, 10))

# preference: default app instead of the player
p.close()
win._player = None
cfg["media_open"] = "default"
import gsexplorer.system as gs  # noqa: E402
opened = []
gs.open_default = lambda path: opened.append(path)
win.open_entry(win.left.current(), e)
check("preference 'default app' bypasses the player", opened == [e.path] and getattr(win, "_player", None) is None)
cfg["media_open"] = "builtin"

# play folder from context action
win.play_folder(D)
p = win._player
check("Play all media in folder", p is not None and len(p.playlist) == 4 and p.index == 0)
win.grab().save(os.path.join(os.environ.get("GX_SHOT_DIR", H), "player_main.png"))
p.close()

print(f"\n{sum(results)}/{len(results)} player checks passed")
sys.exit(0 if all(results) else 1)
